  init(
    _ unexpectedBeforeLeftParen: RawUnexpectedNodesSyntax? = nil,
    leftParen: RawTokenSyntax,
    _ unexpectedBetweenLeftParenAndElements: RawUnexpectedNodesSyntax? = nil,
    elements: RawYieldedExpressionListSyntax,
    _ unexpectedBetweenElementsAndRightParen: RawUnexpectedNodesSyntax? = nil,
    rightParen: RawTokenSyntax,
    _ unexpectedAfterRightParen: RawUnexpectedNodesSyntax? = nil,
    arena: __shared RawSyntaxArena
  ) {
    self.init(unchecked: RawSyntax.makeYieldedExpressionsClause(
      unexpectedBeforeLeftParen?.raw,
      leftParen: leftParen.raw,
      unexpectedBetweenLeftParenAndElements?.raw,
      elements: elements.raw,
      unexpectedBetweenElementsAndRightParen?.raw,
      rightParen: rightParen.raw,
      unexpectedAfterRightParen?.raw,
      arena: arena
    ))
  }

  var unexpectedBeforeLeftParen: RawUnexpectedNodesSyntax? {
    layoutView.unexpectedSlot(at: 0).map(RawUnexpectedNodesSyntax.init(raw:))
  }

  var leftParen: RawTokenSyntax {
    layoutView.realChild(at: 0).map(RawTokenSyntax.init(raw:))!
  }

  var unexpectedBetweenLeftParenAndElements: RawUnexpectedNodesSyntax? {
    layoutView.unexpectedSlot(at: 1).map(RawUnexpectedNodesSyntax.init(raw:))
  }

  var elements: RawYieldedExpressionListSyntax {
    layoutView.realChild(at: 1).map(RawYieldedExpressionListSyntax.init(raw:))!
  }

  var unexpectedBetweenElementsAndRightParen: RawUnexpectedNodesSyntax? {
    layoutView.unexpectedSlot(at: 2).map(RawUnexpectedNodesSyntax.init(raw:))
  }

  var rightParen: RawTokenSyntax {
    layoutView.realChild(at: 2).map(RawTokenSyntax.init(raw:))!
  }

  var unexpectedAfterRightParen: RawUnexpectedNodesSyntax? {
    layoutView.unexpectedSlot(at: 3).map(RawUnexpectedNodesSyntax.init(raw:))
  }
}
